#!/usr/bin/env bash
# HoleShot HUD 0.24.2 (source public on GitHub under the MIT licence: the release files and the source).
# The folder holds the three files of https://github.com/LeadingTrendTechnologies/HoleshotHUD/releases/tag/v0.24.2, by
# their names: Holeshot-HUD-0.24.2-windows-x64.zip, Holeshot-HUD-0.24.2-windows-x64.zip.minisig and HoleshotHUD-Setup.exe.
# This script unpacks the zip into zip/.
# The second argument is a checkout of https://github.com/LeadingTrendTechnologies/HoleshotHUD at
# 5f4905e94f2423cc67c79a4bf7b684c31dd13cf7 (tag v0.24.2), with its history.
# Needs GNU binutils, file, unzip, python3 with the cryptography package (minisig.py), innoextract (1.9) and, for
# release-api, the network.
. "$(dirname "$0")/../ev.sh"
(cd "$R" && rm -rf zip && mkdir zip && unzip -q -d zip Holeshot-HUD-0.24.2-windows-x64.zip)
ev files "sha256sum Holeshot-HUD-0.24.2-windows-x64.zip Holeshot-HUD-0.24.2-windows-x64.zip.minisig HoleshotHUD-Setup.exe zip/*"
ev file "unzip -l Holeshot-HUD-0.24.2-windows-x64.zip; file HoleshotHUD-Setup.exe zip/*"
# The installer is Inno Setup 6.7.0; innoextract 1.9 can't unpack that version (so its files weren't read from it).
ev setup "strings -n 8 HoleshotHUD-Setup.exe | grep -m3 'Inno Setup'; innoextract -l HoleshotHUD-Setup.exe"
# The scripts, README and licences in the zip are the repository's files at the commit, apart from line endings (CRLF);
# THIRD-PARTY.txt is written by tools/third-party.ps1 in the build and isn't in the repository.
ev same-as-source "for p in 'Install.ps1:installer/install.ps1' 'Install.bat:installer/install.bat' 'Install-Plugin.ps1:installer/install-plugin.ps1' 'Uninstall.ps1:installer/uninstall.ps1' 'Uninstall.bat:installer/uninstall.bat' 'README.txt:installer/README.txt' 'LICENSE:LICENSE' 'OFL.txt:overlay/hud/fonts/OFL.txt'; do a=\"\${p%%:*}\"; b=\"\${p##*:}\"; cmp -s <(tr -d '\\r' < \"zip/\$a\") <(tr -d '\\r' < \"\$SRC/\$b\") && echo \"same apart from line endings: zip/\$a = \$b at the commit\" || echo \"DIFFERENT: zip/\$a and \$b\"; done"
# The overlay carries the plugin inside it, byte for byte, and writes it into the game (overlay/src/plugin.rs line 14).
ev embedded-dlo "python3 -I -c 'import sys; d=open(sys.argv[1],\"rb\").read(); p=open(sys.argv[2],\"rb\").read(); i=d.find(p); print(\"Holeshot-HUD.dlo (\", len(p), \"bytes) found whole inside Holeshot-HUD.exe at offset\", hex(i) if i >= 0 else None)' zip/Holeshot-HUD.exe zip/Holeshot-HUD.dlo"
for f in Holeshot-HUD.dlo Holeshot-HUD.exe; do
  ev $f.objdump-p "objdump -p zip/$f | awk '/^The Function Table|^PE File Base Relocations/{exit} 1'"
  ev $f.objdump-h "objdump -h zip/$f"
  ev $f.iat "iat.py zip/$f"
done
ev signature "objdump -p zip/Holeshot-HUD.exe zip/Holeshot-HUD.dlo HoleshotHUD-Setup.exe | grep -E 'file format|Security Directory'"
# The zip's minisign signature, checked with the public key the updater carries (overlay/src/update.rs line 19), which
# is in the release program too; and the same check on a cut copy of the zip, which must fail.
ev minisign "cat Holeshot-HUD-0.24.2-windows-x64.zip.minisig; K=\$(grep -oE 'RW[A-Za-z0-9+/=]{54}' \"\$SRC/overlay/src/update.rs\"); echo \"key in update.rs: \$K\"; echo \"times in Holeshot-HUD.exe: \$(strings -n 20 zip/Holeshot-HUD.exe | grep -c \"\$K\")\"; minisig.py \"\$K\" Holeshot-HUD-0.24.2-windows-x64.zip Holeshot-HUD-0.24.2-windows-x64.zip.minisig; echo '--- a cut copy of the zip:'; head -c 1000000 Holeshot-HUD-0.24.2-windows-x64.zip > \"\$W/cut.zip\"; minisig.py \"\$K\" \"\$W/cut.zip\" Holeshot-HUD-0.24.2-windows-x64.zip.minisig | grep 'file signature'"
# What the plugin imports: the crash handler, the shared memory and its access list; and what it doesn't (registry
# writes, network, code patching, other processes, starting programs).
ev imports-dlo "objdump -p zip/Holeshot-HUD.dlo | grep 'DLL Name'; iat.py zip/Holeshot-HUD.dlo | grep -E 'SetUnhandledExceptionFilter|CreateFileMappingW|MapViewOfFile|OpenProcessToken|AddAccessAllowedAce|SetSecurityDescriptorDacl|LoadLibraryW|GetProcAddress|VirtualProtect'; echo '--- absent:'; iat.py zip/Holeshot-HUD.dlo | grep -iE 'RegCreateKey|RegSetValue|ws2_32|wsock|wininet|winhttp|urlmon|user32|WriteProcessMemory|ReadProcessMemory|OpenProcess\\b|CreateRemoteThread|CreateProcess|ShellExecute|WinExec|AddVectoredExceptionHandler' || echo 'none of: registry writes, network, user32 (no key reads), Read/WriteProcessMemory, OpenProcess, CreateRemoteThread, CreateProcess, ShellExecute, WinExec, AddVectoredExceptionHandler'"
# The plugin's three VirtualProtect calls (IAT slot 0x18003e2e8) all take the plugin's own .fptable section
# (0x18005e000, 0x100 bytes), a table of the statically linked MSVC C runtime, not the game's code.
ev virtualprotect "objdump -h zip/Holeshot-HUD.dlo | grep -E 'fptable'; objdump -d zip/Holeshot-HUD.dlo | grep -E '# 0x18003e2e8|# 0x18005e000'"
# The plugin's in-game HUD, layout editor and key reads (src/hud, src/layout.cpp) are built only with MXBO_INGAME_HUD=1.
ev plugin-build "grep -nE 'ClCompile Include|AdditionalDependencies' \"\$SRC/mxbo.vcxproj\""
ev imports-exe "iat.py zip/Holeshot-HUD.exe | grep -E 'RegSetValueExW|RegDeleteValueW|GetAsyncKeyState|ClipCursor|SetWindowPos|OpenProcess|TerminateProcess|CreateToolhelp32Snapshot|Module32FirstW|IcmpSendEcho|GetExtendedTcpTable|WSAStartup|OpenFileMappingW|XInputGetState|CreateProcessW|ShellExecuteW'; echo '--- absent:'; iat.py zip/Holeshot-HUD.exe | grep -E 'WriteProcessMemory|ReadProcessMemory|VirtualAllocEx|CreateRemoteThread|SetWindowsHookEx|SendInput|keybd_event|mouse_event' || echo 'none of: WriteProcessMemory, ReadProcessMemory, VirtualAllocEx, CreateRemoteThread, SetWindowsHookEx, SendInput, keybd_event, mouse_event'"
# Web addresses in the two program files.
ev strings-urls "for f in zip/Holeshot-HUD.exe zip/Holeshot-HUD.dlo; do echo \"== \$f\"; strings -n 6 \$f | grep -oE 'https?://[A-Za-z0-9./{}_?=-]+' | sort -u; done"
# The presence service in the source (overlay/src/presence.rs) isn't built: main.rs declares no presence module and
# the overlay holds no workers.dev address.
ev presence-absent "grep -n '^mod ' \"\$SRC/overlay/src/main.rs\"; grep -c 'mod presence' \"\$SRC/overlay/src/main.rs\"; strings -n 6 zip/Holeshot-HUD.exe | grep -c -iE 'workers\\.dev|holeshot-presence'"
# The settings and their defaults (HudConfig::new): all widgets off, the update check on, no auto-update, no start-up
# entries, no stream server.
ev src-defaults "cd \"\$SRC\" && grep -nE '^ +show: false,|^ +(game_ui|start_with_windows|open_with_game|close_with_game|stream_enabled|auto_update_on_launch): false,|check_for_updates: true,' overlay/hud/src/config.rs; grep -nE '\"(Check for updates|Update automatically on launch|Open when Windows starts|Open when MX Bikes opens|MX Bikes menus|Browser Source)\"' overlay/src/settings/app.rs"
# The updater: when it runs (only with "Check for updates" on), where it looks, what it checks before it replaces the
# overlay and the plugin: GitHub's SHA-256, then the minisign signature against the key in the program.
ev src-update "cd \"\$SRC\" && grep -nE 'check_for_updates|auto_update_on_launch|update::check|apply_on_launch' overlay/src/main.rs; grep -nE 'releases/latest|\"digest\"|sha256:|starts_with\\(\"https://github.com|got != rel.digest|UPDATE_PUBLIC_KEY|minisig|signature_is_valid|minisign::verify|fs::copy\\(&src_exe|join\\(PLUGIN_DLO\\)|const UA' overlay/src/update.rs; grep -nE 'Hit::CheckForUpdates =>|c.check_for_updates = |c.auto_update_on_launch = false' overlay/src/settings/dispatch.rs"
# Every connection in the overlay's source: the update check, feedback, ICMP ping, web pages it shows, the local server
# and its Origin check (a request whose Origin isn't 127.0.0.1 or localhost gets 403).
ev src-network "cd \"\$SRC\" && grep -rnE 'ureq::|\\.post\\(|IcmpSendEcho\\(|FALLBACK: u32|TcpListener::bind|origin_is_local|host == \"127.0.0.1\"|HOME_URL: &str|mxb-ranked.com/Rider|cbrservers.com/player|holeshot-hud.vercel.app' overlay/src --include=*.rs | grep -v '/tests/'"
# What a feedback report carries (the race log's file path cut to its name), and when replies are fetched.
ev src-feedback "cd \"\$SRC\" && grep -nE 'attach_log: true|fn send\\(|\\\\\"kind\\\\\":|log_name|redact_log_file_field|fn tick\\(settings_open|tickets_lock\\(\\).is_empty|fn fetch_tickets' overlay/src/feedback.rs; grep -nE '\\\\\"v\\\\\":1,\\\\\"file\\\\\"|\\\\\"evt\\\\\":\\\\\"place\\\\\"|\\\\\"n\\\\\":\\{race_num\\}' overlay/src/record.rs; grep -n 'public: false' api/feedback.js"
# Registry writes: the AppCompatFlags value for mxbikes.exe is no longer set (plugin and overlay); the overlay and the
# uninstallers only take DISABLEDXMAXIMIZEDWINDOWEDMODE out of it; the Run values (overlay); what the uninstallers remove.
ev src-registry "cd \"\$SRC\" && grep -nE 'AppCompatFlags|DISABLEDXMAXIMIZEDWINDOWEDMODE|Reg[A-Z][A-Za-z]+\\(' src/*.cpp src/*.h || echo 'plugin: no registry call'; grep -rnE 'ensure_disable|clear_disable_fullscreen_optimizations' overlay/src --include=*.rs; grep -nE 'AppCompatFlags|const FLAG|RegSetValueExW\\(|RegDeleteValueW\\(' overlay/src/compat.rs; grep -nE 'RUN_KEY|RUN_GAME|wait-for-game' overlay/src/startup.rs | head -8; echo '--- in the uninstallers:'; grep -nE 'HKCU|AppCompat|DISABLEDX|Invoke-UndoGameFiles|Clear-GameCompatFlag|Remove-TempLogs|undo-game-files' installer/uninstall.ps1 overlay/src/uninstall.rs; grep -nE 'UninstallRun|Uninstall.ps1' installer/holeshot.iss"
# Files written into the game's folder: the plugin, the pitboard override, the menu pack; and what is deleted.
ev src-gamefiles "cd \"\$SRC\" && grep -nE 'fs::write\\(&dest|remove_legacy_plugin|LEGACY_PLUGIN_FILE: &str|PLUGIN_FILE: &str' overlay/src/plugin.rs; grep -nE 'misc|pitboard.cfg|MARKER_FILE: &str|fs::write\\(&cfg_path|pitboard_shown_anywhere' overlay/src/stock_pitboard.rs; grep -nE 'BAK_DIR: &str|MANIFEST: &str' overlay/src/game_ui/mod.rs; grep -nE 'write_english_labels\\(ui|backup_if_needed\\(ui|copy_dir\\(bak, ui\\)|fn delete_backup|remove_dir_all\\(bak\\)|ui.pkz' overlay/src/game_ui/pack.rs; grep -nE 'english.str\\\"\\)|patch_str_pair\\(&raw' overlay/src/game_ui/io.rs; grep -nE 'Copy-Item|Remove-Item' installer/install-plugin.ps1 installer/install.ps1"
# Keys and input: the plugin's Ctrl and mouse reads, the overlay's settings key, F9, mouse, and the cursor clip.
ev src-keys "cd \"\$SRC\" && grep -nE 'GetAsyncKeyState|keyDown\\(VK_|GetForegroundWindow' src/layout.cpp; grep -nE 'GetAsyncKeyState\\(' overlay/src/main.rs overlay/src/stance.rs; grep -nE 'ClipCursor\\(Some' overlay/src/compat.rs"
# Crash handler in the plugin.
ev src-crash "cd \"\$SRC\" && grep -nE 'SetUnhandledExceptionFilter|MiniDumpWriteDump\"|crash-|EXCEPTION_CONTINUE_SEARCH' src/crash_log.cpp"
# Shared memory: the names, the rider data in it, and its access list: your Windows account and SYSTEM (default
# security if that can't be built).
ev src-shm "cd \"\$SRC\" && grep -nE 'define MXBO_(SHM|CMD)_NAME |char name\\[MXBO_NAME\\]|serverName|eventGuid' src/shm/mxbo_shm.h; grep -nE 'CreateFileMappingW|AddAccessAllowedAce|SECURITY_LOCAL_SYSTEM_RID|TokenUser|attributes = nullptr' src/shm_writer.cpp"
# Steam files the overlay reads: the registry, libraryfolders.vdf (game folder), loginusers.vdf (signed-in account).
ev src-steam "cd \"\$SRC\" && grep -nE 'libraryfolders.vdf|loginusers.vdf|ActiveUser|fn local_steam_id64|fn ranked_url_from_steam_id64|fn cbr_url_from_steam_id64' overlay/src/plugin.rs; grep -nE 'libraryfolders|Valve' installer/install-plugin.ps1"
# The MyMXB page: the script the overlay adds to that site hides and removes its ad slots.
ev src-mymxb "cd \"\$SRC\" && grep -nE 'adsbygoogle|mymxb-ad-hide|node.remove\\(\\)|with_initialization_script|open-browser' overlay/src/settings/mymxb.rs | head -12"
# The release on GitHub: who uploaded the files, and the Release workflow run for the tag at the commit (network).
ev release-api "curl -sS https://api.github.com/repos/LeadingTrendTechnologies/HoleshotHUD/releases/tags/v0.24.2 | python3 -I -c 'import json,sys; d=json.load(sys.stdin); print(\"release\", d[\"tag_name\"], \"author\", d[\"author\"][\"login\"], \"published\", d[\"published_at\"]); [print(a[\"name\"], \"uploaded by\", a[\"uploader\"][\"login\"], a[\"digest\"], a[\"updated_at\"]) for a in d[\"assets\"]]'; curl -sS 'https://api.github.com/repos/LeadingTrendTechnologies/HoleshotHUD/actions/runs?head_sha=5f4905e94f2423cc67c79a4bf7b684c31dd13cf7' | python3 -I -c 'import json,sys; [print(r[\"name\"], r[\"event\"], r[\"head_branch\"], r[\"head_sha\"], r[\"conclusion\"], r[\"created_at\"], r[\"updated_at\"], r[\"html_url\"]) for r in json.load(sys.stdin)[\"workflow_runs\"]]'"
# The build: the Release workflow, the toolchain and the lock file.
ev deps "cd \"\$SRC\" && grep -nE 'tags:|uses:|cargo build|choco install|msbuild mxbo|files:|minisig|sign-update|HOLESHOT_UPDATE_SECRET_KEY' .github/workflows/release.yml; ls rust-toolchain rust-toolchain.toml overlay/rust-toolchain.toml 2>&1; git ls-files | grep -E 'Cargo.lock\$'; grep -nE '^(ureq|wry|zip|sha2|minisign|rusqlite) =' overlay/Cargo.toml"
# The repository: licence (MIT), prebuilt program files (the website demo's wasm; the .pyc of 0.24.0 is gone), and the
# history up to the commit.
ev repo-files "cd \"\$SRC\" && git ls-files | grep -iE 'licen|copying|OFL'; head -3 LICENSE; echo '--- prebuilt program files:'; git ls-files | grep -E '\\.(dll|lib|exe|dlo|so|wasm|pyc|o|obj)\$' | while read f; do file \"\$f\"; done; echo '--- the wasm and the last commits that changed it and its source:'; git log -1 --format='%h %ad %s' --date=short -- web/pkg/mxbo_web_preview_bg.wasm; git log -1 --format='%h %ad %s' --date=short -- web-preview overlay/hud/src; echo '--- the commit that last built the wasm changed its source with it:'; git show --stat --format='%h %ad' --date=short \$(git log -1 --format=%h -- web/pkg/mxbo_web_preview_bg.wasm) -- web-preview web/pkg | grep -E '^[0-9a-f]{7} |web-preview/|_bg.wasm '; echo '--- removed since v0.24.0:'; git diff --stat 3ffdbf366023c19e1741178e39b5704a91728819 5f4905e94f2423cc67c79a4bf7b684c31dd13cf7 -- overlay/hud/assets/__pycache__; echo '--- history:'; git log --oneline 5f4905e94f2423cc67c79a4bf7b684c31dd13cf7 | wc -l; git log --format='%ad' --date=short 5f4905e94f2423cc67c79a4bf7b684c31dd13cf7 | sed -n '1p;\$p'; git log --format='%ad' --date=short 5f4905e94f2423cc67c79a4bf7b684c31dd13cf7 | sort -u | wc -l"
# Third-party code and credits: the release's THIRD-PARTY.txt against the crates the program is built from.
ev strings-thirdparty "echo '== credits in the release README'; grep -niE 'font awesome|licen|credit|thanks|THIRD' zip/README.txt; echo '== THIRD-PARTY.txt: header, crate lines, fonts'; head -3 zip/THIRD-PARTY.txt; grep -cE '^[a-z0-9_-]+ [0-9][^ ]* \\(' zip/THIRD-PARTY.txt; grep -E 'Exo 2|Teko|Goldman|Montserrat|Roboto' zip/THIRD-PARTY.txt; echo '== a few of the crates the program uses, in THIRD-PARTY.txt'; grep -E '^(ureq|wry|minisign|rusqlite|libsqlite3-sys|zip|sha2|hidapi|windows) ' zip/THIRD-PARTY.txt; echo '== crates in the lock file (all targets, with the workspace own)'; grep -c '^name = ' \"\$SRC/overlay/Cargo.lock\"; echo '== the plugin: its only outside code is the game API header'; cd \"\$SRC\" && git ls-files src/vendor"
money zip/Holeshot-HUD.exe zip/Holeshot-HUD.dlo zip/README.txt
# The Windows runs (lab/results/holeshot-0.24.2/): the two rides against the bare demo, and the test-host runs.
export RES="$OUT/../../results/holeshot-0.24.2"
ev runs "cd \"\$RES\" && echo '== real game: steps (all three reached the track)'; for r in baseline ride ride-keys; do echo \"-- \$r\"; grep -E 'to-track|key-|ride' \"\$r-windows/host.log\"; done; echo '== real game: files written outside the game folder, against the baseline (texture cache names are random)'; for r in ride ride-keys; do echo \"-- \$r\"; diff <(sed -E 's/textures\\\\[a-z0-9]{8}/textures\\\\<random>/' \"baseline-windows/outside.txt\" | sort -u) <(sed -E 's/textures\\\\[a-z0-9]{8}/textures\\\\<random>/' \"\$r-windows/outside.txt\" | sort -u); done; echo '== real game: registry writes not in the baseline (none to AppCompatFlags)'; for r in ride ride-keys; do echo \"-- \$r\"; diff <(sort -u \"baseline-windows/registry.txt\") <(sort -u \"\$r-windows/registry.txt\") | grep '^>'; grep -c AppCompatFlags \"\$r-windows/registry.txt\"; done; echo '== network'; for r in ride ride-keys overlay overlay-wait setup bystander-crash; do echo \"-- \$r\"; cat \"\$r-windows/network.txt\"; done; echo '== overlay: registry'; cat \"overlay-windows/registry.txt\"; echo '== overlay: files written outside its folder'; grep -E 'WriteFile|SetRename' \"overlay-windows/outside.txt\" | sort -u; echo '== setup: processes started'; zcat \"setup-windows/raw/procmon.csv.gz\" | grep 'Process Create' | cut -d, -f2,5; echo '== bystander'; grep -E 'Startup\\(|untouched|changed|clean exit|crash|key' \"bystander-crash-windows/host.log\" | sort | uniq -c"
